<?php
if(!defined('UNIOR_INICIADO')){http_response_code(403);exit;}
auth(true);
require_once __DIR__.'/graficos_reportes.php';
$soloTipos=$p==='reporte_tipos';
$soloPlanilla=$p==='reporte_planilla';
$titulo=$soloTipos?'Inscritos por tipo de participante':($soloPlanilla?'Inscritos por descuento de planilla':'Inscritos presenciales y en línea');
$nombreDimension=$soloTipos?'Tipo de participante':'Carrera';
$evento=(int)($_GET['event_id']??0);$usuarioFiltro=(int)($_GET['usuario_id']??0);
$desde=trim((string)($_GET['desde']??''));$hasta=trim((string)($_GET['hasta']??''));
$buscar=trim((string)($_GET['buscar']??''));$carrera=trim((string)($_GET['carrera']??''));$origen=trim((string)($_GET['origen']??''));
$modalidad=trim((string)($_GET['modalidad']??''));
$where=["r.status<>'Anulado'"];$args=[];
$esGrupo="(r.codigo_grupo IS NOT NULL AND r.codigo_grupo<>'')";
if($modalidad==='grupo')$where[]=$esGrupo;elseif($modalidad==='individual')$where[]='NOT '.$esGrupo;
if($soloPlanilla){$where[]="r.payment_method='Descuento por planilla'";}
if($evento){$where[]='r.event_id=?';$args[]=$evento;}
if($usuarioFiltro){$where[]='r.created_by=?';$args[]=$usuarioFiltro;}
if($carrera!==''){$where[]='r.carrera=?';$args[]=$carrera;}
if($origen==='presencial')$where[]='r.created_by IS NOT NULL';
elseif($origen==='linea')$where[]='r.created_by IS NULL';
if($buscar!==''){$where[]="(CONCAT(r.first_name,' ',r.last_name) LIKE ? OR r.ci LIKE ?)";array_push($args,'%'.$buscar.'%','%'.$buscar.'%');}
foreach(['desde'=>'>=','hasta'=>'<='] as $campo=>$op){$valor=$$campo;if($valor!==''){$f=DateTime::createFromFormat('!Y-m-d',$valor);if(!$f||$f->format('Y-m-d')!==$valor){http_response_code(400);exit('Fecha no válida.');}$where[]='r.created_at'.$op.'?';$args[]=$valor.($campo==='desde'?' 00:00:00':' 23:59:59');}}
if($desde!==''&&$hasta!==''&&$desde>$hasta){http_response_code(400);exit('La fecha inicial debe ser anterior a la final.');}
$base=' FROM registrations r JOIN events e ON e.id=r.event_id LEFT JOIN users u ON u.id=r.created_by WHERE '.implode(' AND ',$where);
$tarifa="CASE WHEN r.payment_method='Descuento por planilla' THEN 0 ELSE r.price END";
$cobrado="CASE WHEN r.payment_method='Descuento por planilla' THEN 0 ELSE r.monto_cobrado END";
$debe="CASE WHEN r.payment_method='Descuento por planilla' THEN 0 ELSE GREATEST(0,r.price-r.monto_cobrado) END";
$sinPlanilla="COALESCE(r.payment_method,'')<>'Descuento por planilla'";
$economia="COALESCE(SUM($tarifa),0) tarifa_reporte,COALESCE(SUM($cobrado),0) cobrado_reporte,COALESCE(SUM($debe),0) saldo_reporte";
$tot=one("SELECT COUNT(*) total_registros,COALESCE(SUM(CASE WHEN NOT $esGrupo AND $sinPlanilla AND r.created_by IS NOT NULL THEN 1 ELSE 0 END),0) total_presenciales,COALESCE(SUM(CASE WHEN NOT $esGrupo AND $sinPlanilla AND r.created_by IS NULL THEN 1 ELSE 0 END),0) total_linea,COALESCE(SUM(CASE WHEN r.payment_method='Descuento por planilla' THEN 1 ELSE 0 END),0) total_planilla,COUNT(DISTINCT CASE WHEN $esGrupo THEN r.codigo_grupo END) total_grupos,COALESCE(SUM(CASE WHEN $esGrupo AND $sinPlanilla THEN 1 ELSE 0 END),0) total_integrantes,COALESCE(SUM(CASE WHEN $esGrupo THEN 0 ELSE 1 END),0) total_individuales,$economia".$base,$args);
$carreraSql=$soloTipos?"COALESCE(NULLIF(TRIM(r.category),''),'Sin categoría')":"COALESCE(NULLIF(TRIM(r.carrera),''),'Sin carrera')";
$porCarrera=all("SELECT $carreraSql carrera_resumen,COUNT(*) total_carrera,COALESCE(SUM(CASE WHEN r.payment_method='Descuento por planilla' THEN 1 ELSE 0 END),0) planilla_carrera,COALESCE(SUM(CASE WHEN NOT $esGrupo AND $sinPlanilla AND r.created_by IS NULL THEN 1 ELSE 0 END),0) linea_carrera,COALESCE(SUM(CASE WHEN NOT $esGrupo AND $sinPlanilla AND r.created_by IS NOT NULL THEN 1 ELSE 0 END),0) presencial_carrera,COALESCE(SUM(CASE WHEN $esGrupo AND $sinPlanilla THEN 1 ELSE 0 END),0) integrantes_carrera,COALESCE(SUM(CASE WHEN $esGrupo THEN 0 ELSE 1 END),0) individuales_carrera,COUNT(DISTINCT CASE WHEN $esGrupo THEN r.codigo_grupo END) grupos_carrera,$economia".$base." GROUP BY $carreraSql ORDER BY total_carrera DESC,carrera_resumen",$args);
$baseAnulados=str_replace("r.status<>'Anulado'","r.status='Anulado'",$base);
$tot['total_anulados']=(int)q('SELECT COUNT(*)'.$baseAnulados,$args)->fetchColumn();
$anuladosPorDimension=all("SELECT $carreraSql carrera_resumen,COUNT(*) anulados_dimension".$baseAnulados." GROUP BY $carreraSql",$args);
$mapa=[];foreach($porCarrera as $fila){$fila['anulados_carrera']=0;$mapa[$fila['carrera_resumen']]=$fila;}
foreach($anuladosPorDimension as $fila){$clave=$fila['carrera_resumen'];if(!isset($mapa[$clave]))$mapa[$clave]=['carrera_resumen'=>$clave,'total_carrera'=>0,'planilla_carrera'=>0,'linea_carrera'=>0,'presencial_carrera'=>0,'integrantes_carrera'=>0,'individuales_carrera'=>0,'grupos_carrera'=>0,'tarifa_reporte'=>0,'cobrado_reporte'=>0,'saldo_reporte'=>0];$mapa[$clave]['anulados_carrera']=(int)$fila['anulados_dimension'];}
$porCarrera=array_values($mapa);
$grupos=all("SELECT r.codigo_grupo grupo_reporte,e.name evento_grupo,COUNT(*) integrantes_reporte,$economia".$base." AND $esGrupo GROUP BY r.codigo_grupo,e.id,e.name ORDER BY e.name,r.codigo_grupo",$args);
$composicion=all("SELECT r.codigo_grupo grupo_reporte,$carreraSql carrera_resumen,COUNT(*) integrantes_carrera".$base." AND $esGrupo GROUP BY r.codigo_grupo,$carreraSql ORDER BY r.codigo_grupo,carrera_resumen",$args);
$detalleCarreras=[];foreach($composicion as $c)$detalleCarreras[$c['grupo_reporte']][]=$c['carrera_resumen'].': '.$c['integrantes_carrera'];
$head=['Registro','Fecha','Participante','CI','Carrera','Correo','Evento','Origen','Modalidad','Grupo','Forma de pago','Inscrito por','Estado','Tarifa Bs','A cuenta Bs','Saldo Bs'];
$valores=fn($r)=>[$r['id'],$r['created_at'],nombreParticipante($r),$r['ci'],$r['carrera'],$r['email'],$r['evento_origen'],$r['created_by']===null?'En línea':'Presencial',empty($r['codigo_grupo'])?'Individual':'En grupo',empty($r['codigo_grupo'])?'—':'G-'.substr($r['codigo_grupo'],0,8),$r['payment_method']??'Sin pago',$r['created_by']===null?'Inscripción en línea':($r['responsable_origen']??'Usuario registrado'),$r['status'],($r['payment_method']??'')==='Descuento por planilla'?0:$r['price'],($r['payment_method']??'')==='Descuento por planilla'?0:$r['monto_cobrado'],($r['payment_method']??'')==='Descuento por planilla'?0:max(0,$r['price']-$r['monto_cobrado'])];
$sql='SELECT r.*,e.name evento_origen,u.name responsable_origen'.$base.' ORDER BY r.id DESC';
if(($_GET['exportar']??'')==='csv'){
 header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="'.($soloTipos?'inscritos_por_tipo':($soloPlanilla?'inscritos_planilla':'inscritos_presenciales_linea')).'.csv"');
 $f=fopen('php://output','w');fwrite($f,"\xEF\xBB\xBF");
 $csv=function(array $v)use($f){fputcsv($f,array_map(fn($v)=>preg_match('/^[\s]*[=+@-]/u',(string)$v)?"'".$v:$v,$v),';');};
 if($soloTipos){$csv(['Tipo de participante','Inscritos','Anulados','Importe Bs','Pagado Bs','Saldo Bs']);foreach($porCarrera as $c)$csv([$c['carrera_resumen'],$c['total_carrera'],$c['anulados_carrera'],$c['tarifa_reporte'],$c['cobrado_reporte'],$c['saldo_reporte']]);$csv(['TOTAL',$tot['total_registros'],$tot['total_anulados'],$tot['tarifa_reporte'],$tot['cobrado_reporte'],$tot['saldo_reporte']]);}
 else{$csv(['Carrera','En línea','Presencial','En grupo (personas)','Por planilla','Total inscritos','Anulados','Importe Bs','Pagado Bs','Saldo Bs']);foreach($porCarrera as $c)$csv([$c['carrera_resumen'],$c['linea_carrera'],$c['presencial_carrera'],$c['integrantes_carrera'],$c['planilla_carrera'],$c['total_carrera'],$c['anulados_carrera'],$c['tarifa_reporte'],$c['cobrado_reporte'],$c['saldo_reporte']]);$csv(['TOTAL',$tot['total_linea'],$tot['total_presenciales'],$tot['total_integrantes'],$tot['total_planilla'],$tot['total_registros'],$tot['total_anulados'],$tot['tarifa_reporte'],$tot['cobrado_reporte'],$tot['saldo_reporte']]);}
 fclose($f);exit;
}
$pagina=max(1,(int)($_GET['pagina']??1));$imprimir=($_GET['imprimir']??'')==='1';
$filas=all($sql.($imprimir?'':' LIMIT 100 OFFSET '.(($pagina-1)*100)),$args);
headerPage($titulo);
?>
