</style>
<div class="card p-4 no-print"><form method="get"><input type="hidden" name="p" value="<?=e($p)?>"><div class="row"><div class="col-md-4"><?php selectField('event_id','Evento',[0=>'Todos']+array_column(all('SELECT id,name FROM events ORDER BY starts_at DESC'),'name','id'),(string)$evento);?></div><div class="col-md-4"><?php selectField('usuario_id','Usuario que inscribió',[0=>'Todos']+array_column(all('SELECT id,name FROM users ORDER BY name'),'name','id'),(string)$usuarioFiltro);?></div><div class="col-md-4"><?php selectField('carrera','Carrera',[''=>'Todas']+carrerasInscripcion(),$carrera);?></div><?php if(!$soloPlanilla):?><div class="col-md-4"><?php selectField('origen','Origen',[''=>'Presencial y en línea','presencial'=>'Presencial','linea'=>'En línea'],$origen);?></div><?php endif?><div class="col-md-4"><?php selectField('modalidad','Modalidad',[''=>'Individual y en grupo','individual'=>'Solo individuales','grupo'=>'Solo integrantes de grupos'],$modalidad);?></div><div class="col-md-4"><?php field('buscar','Nombre / CI',$buscar,'text',false);?></div><div class="col-md-2"><?php field('desde','Desde',$desde,'date',false);?></div><div class="col-md-2"><?php field('hasta','Hasta',$hasta,'date',false);?></div></div><button class="btn btn-primary">Generar reporte</button> <button class="btn btn-success" name="exportar" value="csv">Exportar Excel (CSV)</button> <a class="btn btn-outline-primary" target="_blank" rel="noopener" href="<?=url(http_build_query(array_merge($_GET,['p'=>$p,'imprimir'=>1])))?>">Imprimir / PDF</a></form></div>
