<p><b>Total inscritos: <?=e($tot['total_registros'])?></b> · Anulados: <?=e($tot['total_anulados'])?> · Por planilla: <?=e($tot['total_planilla'])?> · Pagado: <?=money($tot['cobrado_reporte'])?> · Saldo: <?=money($tot['saldo_reporte'])?></p>
<p class="nota-reporte">Cada persona cuenta una sola vez: en línea, presencial, en grupo o por planilla. Por planilla se cuenta aparte, sin repetir en las otras columnas. Los anulados se muestran aparte y no suman dinero.</p>
<?php if($soloTipos):?><h4>Cantidad y dinero por tipo de participante</h4><div class="table-responsive"><table class="table table-bordered table-striped tabla-resumen-simple"><thead><tr><th>Tipo de participante</th><th>Inscritos</th><th>Anulados</th><th>Importe Bs</th><th>Pagado Bs</th><th>Saldo Bs</th></tr></thead><tbody><?php foreach($porCarrera as $c):?><tr><td><?=e($c['carrera_resumen'])?></td><td><?=e($c['total_carrera'])?></td><td><?=e($c['anulados_carrera'])?></td><td><?=money($c['tarifa_reporte'])?></td><td><?=money($c['cobrado_reporte'])?></td><td><?=money($c['saldo_reporte'])?></td></tr><?php endforeach?></tbody><tfoot><tr><th>TOTAL</th><th><?=e($tot['total_registros'])?></th><th><?=e($tot['total_anulados'])?></th><th><?=money($tot['tarifa_reporte'])?></th><th><?=money($tot['cobrado_reporte'])?></th><th><?=money($tot['saldo_reporte'])?></th></tr></tfoot></table></div><?php else:?><h4>Inscritos y dinero por carrera</h4><div class="table-responsive"><table class="table table-bordered table-striped tabla-resumen-simple"><thead><tr><th>Carrera</th><th>En línea</th><th>Presencial</th><th>En grupo<br><small>(personas)</small></th><th>Por planilla</th><th>Total inscritos</th><th>Anulados</th><th>Importe Bs</th><th>Pagado Bs</th><th>Saldo Bs</th></tr></thead><tbody><?php foreach($porCarrera as $c):?><tr><td><?=e($c['carrera_resumen'])?></td><td><?=e($c['linea_carrera'])?></td><td><?=e($c['presencial_carrera'])?></td><td><?=e($c['integrantes_carrera'])?></td><td><?=e($c['planilla_carrera'])?></td><td><b><?=e($c['total_carrera'])?></b></td><td><?=e($c['anulados_carrera'])?></td><td><?=money($c['tarifa_reporte'])?></td><td><?=money($c['cobrado_reporte'])?></td><td><?=money($c['saldo_reporte'])?></td></tr><?php endforeach?><?php if(!$porCarrera):?><tr><td colspan="10">No hay inscritos para estos filtros.</td></tr><?php endif?></tbody><tfoot><tr><th>TOTAL</th><th><?=e($tot['total_linea'])?></th><th><?=e($tot['total_presenciales'])?></th><th><?=e($tot['total_integrantes'])?></th><th><?=e($tot['total_planilla'])?></th><th><?=e($tot['total_registros'])?></th><th><?=e($tot['total_anulados'])?></th><th><?=money($tot['tarifa_reporte'])?></th><th><?=money($tot['cobrado_reporte'])?></th><th><?=money($tot['saldo_reporte'])?></th></tr></tfoot></table></div>
<?php endif?><p class="nota-reporte">Importe: total de inscripciones. Pagado: dinero confirmado. Saldo: lo que falta pagar. Por planilla solo suma personas, no dinero.</p>
<div class="tortas-reportes"><?php tortaReporte($porCarrera,'total_carrera','Inscritos por '.($soloTipos?'tipo de participante':'carrera'));tortaReporte($porCarrera,'cobrado_reporte','Dinero pagado por '.($soloTipos?'tipo de participante':'carrera'),true);?></div>
<?php if(!$soloTipos):?><details class="mt-3 detalle-opcional"><summary>Ver detalle de grupos</summary>
<h4 class="mt-4">Grupos separados · <?=e($tot['total_grupos'])?> grupos</h4><div class="table-responsive"><table class="table table-bordered reporte-detalle-grupos"><thead><tr><th>Grupo</th><th>Evento</th><th>Integrantes</th><th>Distribución por carrera</th><th>Tarifa Bs</th><th>A cuenta Bs</th><th>Saldo Bs</th></tr></thead><tbody><?php foreach($grupos as $g):?><tr><td><span class="grupo-etiqueta" title="<?=e($g['grupo_reporte'])?>">G-<?=e(substr($g['grupo_reporte'],0,8))?></span></td><td><?=e($g['evento_grupo'])?></td><td><?=e($g['integrantes_reporte'])?></td><td><?=e(implode(' · ',$detalleCarreras[$g['grupo_reporte']]??[]))?></td><td><?=money($g['tarifa_reporte'])?></td><td><?=money($g['cobrado_reporte'])?></td><td><?=money($g['saldo_reporte'])?></td></tr><?php endforeach?><?php if(!$grupos):?><tr><td colspan="7">No hay grupos para los filtros seleccionados.</td></tr><?php endif?></tbody></table></div><p class="nota-reporte">Si filtra una carrera o una persona, cada grupo muestra solamente sus integrantes que coinciden con esos filtros.</p>
</details>
<?php endif?><details class="mt-3 detalle-opcional"><summary>Ver lista de participantes</summary>
<h4 class="mt-4">Detalle de participantes</h4><div class="table-responsive"><table class="table table-bordered table-striped tabla-origen"><thead><tr><?php foreach($head as $h):?><th scope="col"><?=e($h)?></th><?php endforeach?></tr></thead><tbody><?php foreach($filas as $fila):?><tr><?php foreach($valores($fila) as $v):?><td><?=e($v)?></td><?php endforeach?></tr><?php endforeach?><?php if(!$filas):?><tr><td colspan="16">No hay inscritos para los filtros seleccionados.</td></tr><?php endif?></tbody></table></div><p class="no-print"><?php if($pagina>1):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['pagina'=>$pagina-1])))?>">Anterior</a><?php endif?> Página <?=e($pagina)?> <?php if($pagina*100<$tot['total_registros']):?><a class="btn btn-outline-primary" href="<?=url(http_build_query(array_merge($_GET,['pagina'=>$pagina+1])))?>">Siguiente</a><?php endif?></p></details></div>
